<script setup>
const props = defineProps({ modelValue: { type: Object, required: true }, errors: { type: Object, default: () => ({}) } })
const emit = defineEmits(['update:modelValue'])
function update(patch) { emit('update:modelValue', { ...props.modelValue, ...patch }) }
function variables() { return Array.isArray(props.modelValue.ai_variables) ? props.modelValue.ai_variables : [] }
function changeVariable(index, key, value) { update({ ai_variables: variables().map((item, i) => i === index ? { ...item, [key]: value } : item) }) }
function add() { update({ ai_variables: [...variables(), { name: '', description: '' }] }) }
function remove(index) { update({ ai_variables: variables().filter((_item, i) => i !== index) }) }
const reference = name => '{{' + '$AI.' + name + '}}'
</script>

<template>
  <section class="agent-tool-fields" aria-label="Configuração da ferramenta do agente">
    <h3>Como o agente usa esta ferramenta</h3><p>Descreva quando ela deve ser chamada e quais dados o agente precisa fornecer.</p>
    <label for="agent-tool-description">Descrição da ferramenta <span>*</span></label><textarea id="agent-tool-description" :value="modelValue.child_description || ''" rows="4" maxlength="300" minlength="20" :aria-invalid="!!errors.child_description" placeholder="Use esta ferramenta para…" @input="update({ child_description: $event.target.value })" /><div class="agent-tool-fields__count">{{ (modelValue.child_description || '').length }} / 300</div><p v-if="errors.child_description" class="agent-tool-fields__error" role="alert">{{ errors.child_description }}</p>
    <div class="agent-tool-fields__heading"><strong>Variáveis fornecidas pela IA</strong><button type="button" @click="add"><v-icon icon="mdi-plus" size="16" />Adicionar</button></div>
    <div v-for="(variable,index) in variables()" :key="index" class="agent-tool-fields__variable"><div><label :for="`ai-variable-name-${index}`">Nome</label><input :id="`ai-variable-name-${index}`" :value="variable.name" placeholder="numero_pedido" spellcheck="false" @input="changeVariable(index,'name',$event.target.value)" /></div><button type="button" :aria-label="`Remover variável ${index + 1}`" @click="remove(index)"><v-icon icon="mdi-trash-can-outline" size="18" /></button><div><label :for="`ai-variable-description-${index}`">Descrição</label><input :id="`ai-variable-description-${index}`" :value="variable.description" placeholder="O número do pedido informado pelo cliente" @input="changeVariable(index,'description',$event.target.value)" /></div><code v-if="variable.name">{{ reference(variable.name) }}</code></div>
    <p v-if="errors.ai_variables" class="agent-tool-fields__error" role="alert">{{ errors.ai_variables }}</p><p v-if="!variables().length">Adicione variáveis para o agente preencher os campos da ação.</p><p class="agent-tool-fields__hint">Use as variáveis na configuração abaixo ou arraste os itens do grupo IA, na entrada.</p>
  </section>
</template>

<style scoped>
.agent-tool-fields{padding:16px;margin-bottom:20px;border:1px solid rgb(var(--cm-line));border-radius:12px;background:rgb(var(--cm-surface-2));color:rgb(var(--cm-fg))}.agent-tool-fields h3{font-size:14px;margin:0 0 8px}.agent-tool-fields p{font-size:12px;line-height:1.6;color:rgb(var(--cm-fg-muted));margin:8px 0 12px}.agent-tool-fields label{display:block;font-size:12px;font-weight:600;margin-bottom:8px}.agent-tool-fields label span{color:rgb(var(--cm-danger))}.agent-tool-fields textarea,.agent-tool-fields input{width:100%;border:1px solid rgb(var(--cm-line-strong));border-radius:8px;padding:10px;background:rgb(var(--cm-surface-1));color:rgb(var(--cm-fg));font:inherit;line-height:1.5;min-width:0}.agent-tool-fields textarea{resize:vertical}.agent-tool-fields textarea:focus,.agent-tool-fields input:focus{outline:2px solid rgb(var(--cm-focus));outline-offset:2px}.agent-tool-fields__count{text-align:right;font:11px var(--trama-font-code,monospace);color:rgb(var(--cm-fg-muted));margin-top:5px}.agent-tool-fields .agent-tool-fields__error{color:rgb(var(--cm-danger))}.agent-tool-fields__heading{display:flex;gap:8px;align-items:center;justify-content:space-between;margin:20px 0 10px}.agent-tool-fields__heading strong{font-size:12px}.agent-tool-fields button{display:flex;align-items:center;justify-content:center;gap:5px;min-height:36px;padding:0 7px;border:1px solid rgb(var(--cm-line-strong));border-radius:8px;font-size:12px;color:rgb(var(--cm-fg))}.agent-tool-fields button:focus-visible{outline:2px solid rgb(var(--cm-focus));outline-offset:2px}.agent-tool-fields__variable{display:grid;grid-template-columns:minmax(0,1fr) 36px;gap:10px;margin-top:12px;padding-top:12px;border-top:1px solid rgb(var(--cm-line))}.agent-tool-fields__variable>div:nth-of-type(2),.agent-tool-fields__variable code{grid-column:1/-1}.agent-tool-fields__variable>button{height:40px;align-self:end;color:rgb(var(--cm-danger))}.agent-tool-fields__variable code{font-size:11px;overflow-wrap:anywhere;color:rgb(var(--cm-fg-muted))}.agent-tool-fields .agent-tool-fields__hint{margin-bottom:0;font-size:11px}
</style>
